import { Body, Controller, Get, Headers, HttpCode, Param, Post, Query } from "@nestjs/common";
import { ApiBearerAuth, ApiHeader, ApiTags } from "@nestjs/swagger";
import { CurrentUser } from "../../common/decorators/current-user.decorator";
import { CorrelationId } from "../../common/decorators/correlation-id.decorator";
import type { AuthenticatedUser } from "../../common/auth/auth-context";
import { ReportsService } from "./reports.service";
import { CreateReportDto, DownloadReportQueryDto } from "./dto/create-report.dto";

/**
 * Reports (Step 8): seven report types, each generated by a background job
 * as an Arabic PDF and a CSV. Any member may call these routes; the service
 * decides per report type and role whether the caller may generate it and
 * whether they get the financial version (report-access.ts), and who may
 * see a generated report.
 */
@ApiBearerAuth()
@ApiTags("reports")
@Controller("reports")
export class ReportsController {
  constructor(private readonly reports: ReportsService) {}

  /** 202: the report (QUEUED); poll `GET /reports/:id` until it is READY or FAILED. */
  @Post()
  @HttpCode(202)
  @ApiHeader({ name: "Idempotency-Key", required: true })
  create(
    @Body() dto: CreateReportDto,
    @CurrentUser() user: AuthenticatedUser,
    @Headers("idempotency-key") idempotencyKey: string | undefined,
    @CorrelationId() correlationId: string,
  ) {
    return this.reports.create(dto, user, idempotencyKey, correlationId);
  }

  @Get()
  list(@CurrentUser() user: AuthenticatedUser) {
    return this.reports.list(user);
  }

  @Get(":id")
  get(@Param("id") id: string, @CurrentUser() user: AuthenticatedUser) {
    return this.reports.get(id, user);
  }

  @Get(":id/download")
  download(@Param("id") id: string, @Query() query: DownloadReportQueryDto, @CurrentUser() user: AuthenticatedUser, @CorrelationId() correlationId: string) {
    return this.reports.download(id, query.format ?? "pdf", user, correlationId);
  }

  @Get(":id/verify")
  verify(@Param("id") id: string, @CurrentUser() user: AuthenticatedUser, @CorrelationId() correlationId: string) {
    return this.reports.verify(id, user, correlationId);
  }
}
